export const front: FrontMatter = {"series": "Dark Seven  ·  Volume One", "titleLine1": "Dark", "titleLine2": "Corridors", "title": "Dark Corridors", "subtitle": "a novel", "meta": "Rocket Valley, Alabama  ·  The Show Me State", "scripture": [{"lines": ["Yea, though I walk through the valley of the shadow of death", "I will fear no evil."], "cite": "Psalm 23:4"}, {"lines": ["The way of the wicked is as darkness:", "they know not at what they stumble."], "cite": "Proverbs 4:19"}], "dedication": "For the ones who wrote the true thing and called it fiction anyway.", "close": ["Dark Seven — Volume One — Dark Corridors", "Rocket Valley, Alabama  ·  The Show Me State"], "constitution": "TheShaneBrain Constitution — All Rights Reserved"};

export const chapters: Chapter[] = [{"id": "ch-01", "number": "Chapter One", "title": "The First Witness", "date": "", "studio": "/audio/chapters/ch-01.mp3", "blocks": [{"id": "ch01-n01", "kind": "narrator", "text": "There is a door on the side of the house that leads to its own small country.", "html": "There is a door on the side of the house that leads to its own small country.", "noIndent": true}, {"id": "ch01-n02", "kind": "narrator", "text": "One room, mostly. A recliner that has learned the exact shape of the man who sits in it. A window angled just right — close enough to see the big house, the kitchen light, the boys' windows, far enough to leave them their peace. That is how The Old Soldier likes it. Near the ones he would die for. Never underfoot. He spent a life learning the difference between guarding a thing and crowding it.", "html": "One room, mostly. A recliner that has learned the exact shape of the man who sits in it. A window angled just right — close enough to see the big house, the kitchen light, the boys' windows, far enough to leave them their peace. That is how The Old Soldier likes it. Near the ones he would die for. Never underfoot. He spent a life learning the difference between guarding a thing and crowding it.", "noIndent": false}, {"id": "ch01-n03", "kind": "narrator", "text": "He is the grandfather. He carried, for a country, a weight he mostly does not set down out loud — you read it in how he holds himself more than in anything he would ever say.", "html": "He is the grandfather. He carried, for a country, a weight he mostly does not set down out loud — you read it in how he holds himself more than in anything he would ever say.", "noIndent": false}, {"id": "ch01-n04", "kind": "narrator", "text": "He goes first. Before anyone. He earned first.", "html": "He goes first. Before anyone. He earned first.", "noIndent": false}, {"id": "ch01-n05", "kind": "narrator", "text": "The dark comes down around him the way it always does in that little room, and somewhere in it, red finds him. Not a lamp. Not a window. Just the one color that ever reaches him in there, arriving and leaving, arriving and leaving. Red. Grey. Red. Grey.", "html": "The dark comes down around him the way it always does in that little room, and somewhere in it, red finds him. Not a lamp. Not a window. Just the one color that ever reaches him in there, arriving and leaving, arriving and leaving. Red. Grey. Red. Grey.", "noIndent": false}, {"id": "ch01-n06", "kind": "narrator", "text": "Because he knows this account before it ever reaches him. He was in it. He is the one who said it.", "html": "Because he knows this account before it ever reaches him. He was in it. He is the one who said it.", "noIndent": false}, {"id": "ch01-n07", "kind": "narrator", "text": "Take this to the room. Don't touch it till you're there.", "html": "<em>Take this to the room. Don't touch it till you're there.</em>", "noIndent": true}, {"id": "ch01-n08", "kind": "narrator", "text": "An errand. A Tuesday. A father handing his boy a small ordinary task on a bright day, the way fathers have since there were fathers. Go do this thing. Come right back. He didn't know. No father ever knows, when he sends his boy out a door, which afternoons come back different. He gave a chore. The road gave back a son with his skull opened crown to nape and a knife in his back and a drive home nobody should have survived. He has carried a lot of weight in his years. That one — the errand — he has carried quietest of all, because how do you set down a thing that was never even your fault, and is still, somehow, entirely yours.", "html": "An errand. A Tuesday. A father handing his boy a small ordinary task on a bright day, the way fathers have since there were fathers. Go do this thing. Come right back. He didn't know. No father ever knows, when he sends his boy out a door, which afternoons come back different. He gave a chore. The road gave back a son with his skull opened crown to nape and a knife in his back and a drive home nobody should have survived. He has carried a lot of weight in his years. That one — the errand — he has carried quietest of all, because how do you set down a thing that was never even your fault, and is still, somehow, entirely yours.", "noIndent": false}, {"id": "ch01-s01", "kind": "spoken", "text": "He would give anything to have kept the boy home that day. He couldn't have known. He would give anything anyway.", "html": "He would give anything to have kept the boy home that day. He couldn't have known. He would give anything anyway.", "audio": "/audio/spoken/ch01-s01.mp3"}, {"id": "ch01-n09", "kind": "narrator", "text": "And here is the whole of what he carries, alone, in the red and the grey: his son went out a door and came back scarred, and became a man, and became a father in his own turn — and that father could not stop the dark that came, later, for his own boy, the one they call Keystone now, the stone that held. Three men. One door, over and over. A grandfather who sent a son. A son who could not shield his own. A boy who is in the light now because the shield finally went up.", "html": "And here is the whole of what he carries, alone, in the red and the grey: his son went out a door and came back scarred, and became a man, and became a father in his own turn — and that father could not stop the dark that came, later, for his own boy, the one they call Keystone now, the stone that held. Three men. One door, over and over. A grandfather who sent a son. A son who could not shield his own. A boy who is in the light now because the shield finally went up.", "noIndent": false}, {"id": "ch01-n10", "kind": "narrator", "text": "Every one of them learned the same terrible, holy thing the hard way: you cannot control the road. You can only teach a child how to walk into a room anyway — staples holding the shirt shut if that's what it costs — and then stand in the door, and pray, and be there when they come back different.", "html": "Every one of them learned the same terrible, holy thing the hard way: you cannot control the road. You can only teach a child how to walk into a room anyway — staples holding the shirt shut if that's what it costs — and then stand in the door, and pray, and be there when they come back different.", "noIndent": false}, {"id": "ch01-n11", "kind": "narrator", "text": "He does not look away from any of it. He receives it. He lets it be true and does not flinch it smaller.", "html": "He does not look away from any of it. He receives it. He lets it be true and does not flinch it smaller.", "noIndent": false}, {"id": "ch01-n12", "kind": "narrator", "text": "That is the only thing a first witness can do for an account like this one — say, without a word: I saw it. I saw what happened to you. I saw what you did about it. I believe every cut.", "html": "That is the only thing a first witness can do for an account like this one — say, without a word: <em>I saw it. I saw what happened to you. I saw what you did about it. I believe every cut.</em>", "noIndent": false}, {"id": "ch01-n13", "kind": "narrator", "text": "Then he sits a minute in the dark, the way he always does after. Then he gets up slow, crosses the little country of his room, and looks out the window at the big house where they are all still up, safe.", "html": "Then he sits a minute in the dark, the way he always does after. Then he gets up slow, crosses the little country of his room, and looks out the window at the big house where they are all still up, safe.", "noIndent": false}, {"id": "ch01-n14", "kind": "narrator", "text": "And he knows, the way old soldiers know, that the shield held. That the boy came back different but came back. That the line goes on.", "html": "And he knows, the way old soldiers know, that the shield held. That the boy came back different but came back. That the line goes on.", "noIndent": true}]}, {"id": "ch-02", "number": "Chapter Two", "title": "The Floor", "date": "", "studio": "/audio/chapters/ch-02.mp3", "blocks": [{"id": "ch02-n01", "kind": "narrator", "text": "The floor came up fast.", "html": "The floor came up fast.", "noIndent": true}, {"id": "ch02-n02", "kind": "narrator", "text": "Not the way floors come up in movies. No slow-motion drift, no swell in the soundtrack, no amber-filtered moment of tragedy to give the scene its shape. Just the sudden strike of hot asphalt, the hollow sound of impact, and the immediate heat of blood. And the raw, animal question of whether the leaking would ever stop.", "html": "Not the way floors come up in movies. No slow-motion drift, no swell in the soundtrack, no amber-filtered moment of tragedy to give the scene its shape. Just the sudden strike of hot asphalt, the hollow sound of impact, and the immediate heat of blood. And the raw, animal question of whether the leaking would ever stop.", "noIndent": false}, {"id": "ch02-n03", "kind": "narrator", "text": "The box cutter made its line. One clean horizontal cut. The line never closed clean. It stayed raised, white against the rest of him, a permanent coordinate.", "html": "The box cutter made its line. One clean horizontal cut. The line never closed clean. It stayed raised, white against the rest of him, a permanent coordinate.", "noIndent": false}, {"id": "ch02-n04", "kind": "narrator", "text": "Rocket Valley. Prom Night. Young men who had not yet learned that the world does not care how young you are when it decides to cut you open.", "html": "Rocket Valley. Prom Night. Young men who had not yet learned that the world does not care how young you are when it decides to cut you open.", "noIndent": false}, {"id": "ch02-b05", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch02-n05", "kind": "narrator", "text": "The afternoon had no idea what it was about to become.", "html": "The afternoon had no idea what it was about to become.", "noIndent": true}, {"id": "ch02-n06", "kind": "narrator", "text": "Warm day. Windows down. A six-lane road shimmering in bright afternoon light, a small car moving through all that ordinary white. Tapioca driving. The Carrier riding passenger. Two kids in the afternoon, ordinary as bread. The errand was simple. His father's hand had passed him something across a console, voice flat and final: Take this to the room. Don't touch it till you're there.", "html": "Warm day. Windows down. A six-lane road shimmering in bright afternoon light, a small car moving through all that ordinary white. Tapioca driving. The Carrier riding passenger. Two kids in the afternoon, ordinary as bread. The errand was simple. His father's hand had passed him something across a console, voice flat and final: <em>Take this to the room. Don't touch it till you're there.</em>", "noIndent": false}, {"id": "ch02-n07", "kind": "narrator", "text": "Then the car pulled up alongside them, pacing. A woman driving. A man folded low in the passenger seat, the kind of man just waiting for a reason. The Carrier's eyes flicked over — less than a look, a glance, the kind that costs nothing on a normal Tuesday. The man took it wrong. Took it as territory. Took it as a challenge written in the language of a world the boy hadn't known he'd entered.", "html": "Then the car pulled up alongside them, pacing. A woman driving. A man folded low in the passenger seat, the kind of man just waiting for a reason. The Carrier's eyes flicked over — less than a look, a glance, the kind that costs nothing on a normal Tuesday. The man took it wrong. Took it as territory. Took it as a challenge written in the language of a world the boy hadn't known he'd entered.", "noIndent": false}, {"id": "ch02-n08", "kind": "narrator", "text": "The bird came up over the door. The Carrier — young, dumb, alive in the way that has no sense of consequence — flipped it right back. Behind the man's eyes the rage caught, hot and instant and out of all proportion. Some men are just holding the match. They're only waiting for a room to walk into.", "html": "The bird came up over the door. The Carrier — young, dumb, alive in the way that has no sense of consequence — flipped it right back. Behind the man's eyes the rage caught, hot and instant and out of all proportion. Some men are just holding the match. They're only waiting for a room to walk into.", "noIndent": false}, {"id": "ch02-n09", "kind": "narrator", "text": "A second car was already moving. Long and full, coming up fast from behind like dogs let off a chain. Six, seven men inside it, faces set. This had never been one man's temper. This was a hunt, with more teeth than the road could see yet. The long car whipped around in front and stood on the brakes. The small car boxed in — no room, no exit, no version of what happened next that didn't start with the passenger window.", "html": "A second car was already moving. Long and full, coming up fast from behind like dogs let off a chain. Six, seven men inside it, faces set. This had never been one man's temper. This was a hunt, with more teeth than the road could see yet. The long car whipped around in front and stood on the brakes. The small car boxed in — no room, no exit, no version of what happened next that didn't start with the passenger window.", "noIndent": false}, {"id": "ch02-n10", "kind": "narrator", "text": "A shape at his window. A line of light in its hand. Before his brain could file the shape as a blade — it was through the open window and through his arm. Muscle, then the deep cold wrongness of bone. Blood sheeting off the elbow onto the door, onto the lane.", "html": "A shape at his window. A line of light in its hand. Before his brain could file the shape as a blade — it was through the open window and through his arm. Muscle, then the deep cold wrongness of bone. Blood sheeting off the elbow onto the door, onto the lane.", "noIndent": false}, {"id": "ch02-n11", "kind": "narrator", "text": "Then Tapioca's voice, wild and certain:", "html": "Then Tapioca's voice, wild and certain:", "noIndent": false}, {"id": "ch02-n12", "kind": "narrator", "text": "Get out — we're surrounded.", "html": "<em>Get out — we're surrounded.</em>", "noIndent": true}, {"id": "ch02-n13", "kind": "narrator", "text": "So they got out.", "html": "So they got out.", "noIndent": true}, {"id": "ch02-n14", "kind": "narrator", "text": "4:15 PM. Two boys stepping into the middle of six screaming lanes, the whole carload closing on them from every side. The horns started. The horns never stopped. A hundred strangers watching from inside their glass and steel, leaning on the only language they had. It changed nothing. He registered it only as weather.", "html": "4:15 PM. Two boys stepping into the middle of six screaming lanes, the whole carload closing on them from every side. The horns started. The horns never stopped. A hundred strangers watching from inside their glass and steel, leaning on the only language they had. It changed nothing. He registered it only as weather.", "noIndent": false}, {"id": "ch02-n15", "kind": "narrator", "text": "The first man jumped him. A second swung — a weapon cracking off the side of his head. White flash. Taste of pennies. He got his hands into the first man anyway. Picked him clean off the road, slammed him onto the asphalt, dropped a knee, closed a hand on the throat. The man's heels were drumming the road. He was winning this one — with zero thoughts of stopping.", "html": "The first man jumped him. A second swung — a weapon cracking off the side of his head. White flash. Taste of pennies. He got his hands into the first man anyway. Picked him clean off the road, slammed him onto the asphalt, dropped a knee, closed a hand on the throat. The man's heels were drumming the road. He was winning this one — with zero thoughts of stopping.", "noIndent": false}, {"id": "ch02-n16", "kind": "narrator", "text": "Then he looked up and saw them. They had Tapioca.", "html": "Then he looked up and saw them. They had Tapioca.", "noIndent": false}, {"id": "ch02-s01", "kind": "spoken", "text": "I let go of the sure thing to save my friend. The only math I've ever known how to do.", "html": "I let go of the sure thing to save my friend. The only math I've ever known how to do.", "audio": "/audio/spoken/ch02-s01.mp3"}, {"id": "ch02-n17", "kind": "narrator", "text": "The instant he turned loose — a hit from the blind side. He got under it, lifted the new man clean off his feet, and threw him into the oncoming lane. A body in the air over white asphalt. The horns. Always the horns.", "html": "The instant he turned loose — a hit from the blind side. He got under it, lifted the new man clean off his feet, and threw him into the oncoming lane. A body in the air over white asphalt. The horns. Always the horns.", "noIndent": false}, {"id": "ch02-n18", "kind": "narrator", "text": "From behind, a fist grabbed his shirt and hauled it up, baring his back. What happened next was so soft-feeling it barely registered — a line drawn down the spine, not a stab but a drawing, slow and bright, the blade doing its slow geography. Then another line across the shoulder blade, the blood running warm into his waistband before the pain even filed its report. Then a fist in his hair, hauling. The head snapped back. The blade opened the back of his skull, crown to nape — one long cold unzipping. The world tipped. Sky where the asphalt should be. A warm curtain coming down over one eye.", "html": "From behind, a fist grabbed his shirt and hauled it up, baring his back. What happened next was so soft-feeling it barely registered — a line drawn down the spine, not a stab but a drawing, slow and bright, the blade doing its slow geography. Then another line across the shoulder blade, the blood running warm into his waistband before the pain even filed its report. Then a fist in his hair, hauling. The head snapped back. The blade opened the back of his skull, crown to nape — one long cold unzipping. The world tipped. Sky where the asphalt should be. A warm curtain coming down over one eye.", "noIndent": false}, {"id": "ch02-n19", "kind": "narrator", "text": "He could feel the neck exposed. Could feel the throat pulled long and bared to the white afternoon. He understood, in the wordless way the body understands before the mind catches up, that this was where the night had always been driving. The next cut was the last one.", "html": "He could feel the neck exposed. Could feel the throat pulled long and bared to the white afternoon. He understood, in the wordless way the body understands before the mind catches up, that this was where the night had always been driving. The next cut was the last one.", "noIndent": false}, {"id": "ch02-n20", "kind": "narrator", "text": "It never fell.", "html": "It never fell.", "noIndent": true}, {"id": "ch02-n21", "kind": "narrator", "text": "Tapioca came over the roof of a car.", "html": "Tapioca came over the roof of a car.", "noIndent": true}, {"id": "ch02-n22", "kind": "narrator", "text": "Over it — spending a body he had no business still standing in — clean over the whole car, arms wide, landing on the man with the blade. The knife went wide. The throat closed.", "html": "Over it — spending a body he had no business still standing in — clean over the whole car, arms wide, landing on the man with the blade. The knife went wide. The throat closed.", "noIndent": false}, {"id": "ch02-s02", "kind": "spoken", "text": "Somebody who had every reason to save his own skin spent it instead. Came over the car for me. I was young. I learned the only theology I've ever fully trusted: the finish doesn't have to land.", "html": "Somebody who had every reason to save his own skin spent it instead. Came over the car for me. I was young. I learned the only theology I've ever fully trusted: the finish doesn't have to land.", "audio": "/audio/spoken/ch02-s02.mp3"}, {"id": "ch02-n23", "kind": "narrator", "text": "He came back down into his own body inside a lake of red. No choreography anymore — a drowning. Swinging every direction at once, blind in one eye, unable to tell his blood from theirs from the road's. In the fog, a blade went into his back and where every other cut had drawn its line and pulled away, this one went to the handle and stayed.", "html": "He came back down into his own body inside a lake of red. No choreography anymore — a drowning. Swinging every direction at once, blind in one eye, unable to tell his blood from theirs from the road's. In the fog, a blade went into his back and where every other cut had drawn its line and pulled away, this one went to the handle and stayed.", "noIndent": false}, {"id": "ch02-n24", "kind": "narrator", "text": "Something in a car's brakes screamed — long, human, wrong. The seven scattered. Gone as fast as they came.", "html": "Something in a car's brakes screamed — long, human, wrong. The seven scattered. Gone as fast as they came.", "noIndent": false}, {"id": "ch02-n25", "kind": "narrator", "text": "Two boys left standing in the middle of a stopped highway, counting their own leaks. What Tapioca carried out of that road is his own to tell.", "html": "Two boys left standing in the middle of a stopped highway, counting their own leaks. What Tapioca carried out of that road is his own to tell.", "noIndent": false}, {"id": "ch02-n26", "kind": "narrator", "text": "The Carrier: the arm open to the bone. The spine. The shoulder blade. The scalp, crown to nape. The knife still in his back. Standing.", "html": "The Carrier: the arm open to the bone. The spine. The shoulder blade. The scalp, crown to nape. The knife still in his back. Standing.", "noIndent": false}, {"id": "ch02-n27", "kind": "narrator", "text": "He got into the car. The knife was still in his back. Every shift was a fresh scream from an arm that was more open than closed. He drove. The red filling the seat. The red on the wheel. The white road unspooling ahead. The car stopping crooked. The door opening. The ground coming up to meet him.", "html": "He got into the car. The knife was still in his back. Every shift was a fresh scream from an arm that was more open than closed. He drove. The red filling the seat. The red on the wheel. The white road unspooling ahead. The car stopping crooked. The door opening. The ground coming up to meet him.", "noIndent": false}, {"id": "ch02-n28", "kind": "narrator", "text": "A crowd gathered the way crowds do — too late and too loud. The last thing in the world was the one color that had been in it the whole time.", "html": "A crowd gathered the way crowds do — too late and too loud. The last thing in the world was the one color that had been in it the whole time.", "noIndent": false}, {"id": "ch02-n29", "kind": "narrator", "text": "And then the black.", "html": "And then the black.", "noIndent": true}, {"id": "ch02-b33", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch02-n30", "kind": "narrator", "text": "The white came back up before he did. Not the blown-out afternoon kind. Fluorescent. Cold. A different white doing a different job. His father was already there. Had beaten the ambulance to the doors.", "html": "The white came back up before he did. Not the blown-out afternoon kind. Fluorescent. Cold. A different white doing a different job. His father was already there. Had beaten the ambulance to the doors.", "noIndent": true}, {"id": "ch02-n31", "kind": "narrator", "text": "Behind the gurney, a line followed him in across the tile — red, dragging, marking the whole length of the hallway. His father didn't sit. There was a chair. He never touched it.", "html": "Behind the gurney, a line followed him in across the tile — red, dragging, marking the whole length of the hallway. His father didn't sit. There was a chair. He never touched it.", "noIndent": false}, {"id": "ch02-n32", "kind": "narrator", "text": "The doctor laid it out plain over a boy seventeen years old, opened in five places:", "html": "The doctor laid it out plain over a boy seventeen years old, opened in five places:", "noIndent": false}, {"id": "ch02-n33", "kind": "narrator", "text": "\"We can close this properly. Thirty thousand stitches, small scarring, but it's going to take most of the night and into tomorrow.\"", "html": "\"We can close this properly. Thirty thousand stitches, small scarring, but it's going to take most of the night and into tomorrow.\"", "noIndent": true}, {"id": "ch02-n34", "kind": "narrator", "text": "\"I've got somewhere to be tonight.\"", "html": "\"I've got somewhere to be tonight.\"", "noIndent": true}, {"id": "ch02-n35", "kind": "narrator", "text": "\"Then it's staples. A hundred of them, give or take. You'll carry the scar the rest of your life.\"", "html": "\"Then it's staples. A hundred of them, give or take. You'll carry the scar the rest of your life.\"", "noIndent": true}, {"id": "ch02-n36", "kind": "narrator", "text": "\"Staples.\"", "html": "\"Staples.\"", "noIndent": true}, {"id": "ch02-n37", "kind": "narrator", "text": "k-CHUNK. The first staple went in like a nail gun closing an argument. Then another. Then the rhythm of it — punch, click, punch, click — laying a line down his spine that the rest of this book would hang its whole binding on. He didn't flinch. There wasn't room left in him to flinch.", "html": "<em>k-CHUNK.</em> The first staple went in like a nail gun closing an argument. Then another. Then the rhythm of it — punch, click, punch, click — laying a line down his spine that the rest of this book would hang its whole binding on. He didn't flinch. There wasn't room left in him to flinch.", "noIndent": false}, {"id": "ch02-b42", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch02-n38", "kind": "narrator", "text": "By nine fifteen the night had gone all the way black, and somewhere in the middle of it a building stood up glowing white against the sky — the one white this book had earned honestly. Their dates did the buttons. Careful hands over a shirt with a hundred staples underneath it, working a collar shut around a neck that had almost not made it to nine o'clock.", "html": "By nine fifteen the night had gone all the way black, and somewhere in the middle of it a building stood up glowing white against the sky — the one white this book had earned honestly. Their dates did the buttons. Careful hands over a shirt with a hundred staples underneath it, working a collar shut around a neck that had almost not made it to nine o'clock.", "noIndent": true}, {"id": "ch02-n39", "kind": "narrator", "text": "Then the doors. Two boys walking into the light — stitched, stapled, upright on will alone.", "html": "Then the doors. Two boys walking into the light — stitched, stapled, upright on will alone.", "noIndent": false}, {"id": "ch02-n40", "kind": "narrator", "text": "He didn't dance. Couldn't. Stood at the edge of the floor instead, the wound still open under the shirt, staples pulling with every breath, and let the light hit his face anyway.", "html": "He didn't dance. Couldn't. Stood at the edge of the floor instead, the wound still open under the shirt, staples pulling with every breath, and let the light hit his face anyway.", "noIndent": false}, {"id": "ch02-b46", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch02-n41", "kind": "narrator", "text": "Morning came up white and ordinary, which felt like its own kind of violence — the world going on plain and daylit like nothing had happened, while a boy walked through it with a hundred staples holding his back together.", "html": "Morning came up white and ordinary, which felt like its own kind of violence — the world going on plain and daylit like nothing had happened, while a boy walked through it with a hundred staples holding his back together.", "noIndent": true}, {"id": "ch02-n42", "kind": "narrator", "text": "That was the day he met The Early Cold. Two people, nothing more than that yet.", "html": "That was the day he met The Early Cold. Two people, nothing more than that yet.", "noIndent": false}, {"id": "ch02-s03", "kind": "spoken", "text": "We trauma bonded and did not even know it.", "html": "We trauma bonded and did not even know it.", "audio": "/audio/spoken/ch02-s03.mp3"}, {"id": "ch02-n43", "kind": "narrator", "text": "He didn't know yet what she'd cost him, or what he'd cost her. He only knew he was still standing, staples and all, and that the standing had to count for something.", "html": "He didn't know yet what she'd cost him, or what he'd cost her. He only knew he was still standing, staples and all, and that the standing had to count for something.", "noIndent": false}, {"id": "ch02-s04", "kind": "spoken", "text": "I was unbearable to live with.", "html": "I was unbearable to live with.", "audio": "/audio/spoken/ch02-s04.mp3"}, {"id": "ch02-n44", "kind": "narrator", "text": "The scar down his spine had already chosen its shape — in a hospital room, under a clock, in the space between a hundred staples and a night he refused to miss. Everything after hung off that line.", "html": "The scar down his spine had already chosen its shape — in a hospital room, under a clock, in the space between a hundred staples and a night he refused to miss. Everything after hung off that line.", "noIndent": false}]}, {"id": "ch-03", "number": "Chapter Three", "title": "The Corridor Opens", "date": "", "studio": "/audio/chapters/ch-03.mp3", "blocks": [{"id": "ch03-n01", "kind": "narrator", "text": "Getting up off the asphalt. Not as a metaphor. Literally getting the boots underneath the hips, standing up, and putting on a collar.", "html": "Getting up off the asphalt. Not as a metaphor. Literally getting the boots underneath the hips, standing up, and putting on a collar.", "noIndent": true}, {"id": "ch03-n02", "kind": "narrator", "text": "The Wire Shop. Floor sales. Pagers, cellular contracts, plastic handsets across a laminate counter scarred with cigarette burns nobody had bothered to sand out, under the buzz of fluorescent ballasts that never fully warmed up — the same indifferent note the hospital room had used, same light doing a different nothing. He kept the feet moving because stopping meant looking down at what was torn open underneath the shirt, and what was underneath was a fresh line that hadn't yet decided how much it was going to cost him.", "html": "The Wire Shop. Floor sales. Pagers, cellular contracts, plastic handsets across a laminate counter scarred with cigarette burns nobody had bothered to sand out, under the buzz of fluorescent ballasts that never fully warmed up — the same indifferent note the hospital room had used, same light doing a different nothing. He kept the feet moving because stopping meant looking down at what was torn open underneath the shirt, and what was underneath was a fresh line that hadn't yet decided how much it was going to cost him.", "noIndent": false}, {"id": "ch03-s01", "kind": "spoken", "text": "Motion is medication.", "html": "Motion is medication.", "audio": "/audio/spoken/ch03-s01.mp3"}, {"id": "ch03-n03", "kind": "narrator", "text": "The body learned the first rule early and applied it without asking the mind's permission. The mind was busy with other things: the child support docket, the bar tab that grew where the child support money should have been, the transactions on no register that covered what the transactions on record couldn't. Pain was easy to kill. That was the first and most dangerous truth the corridor taught him.", "html": "The body learned the first rule early and applied it without asking the mind's permission. The mind was busy with other things: the child support docket, the bar tab that grew where the child support money should have been, the transactions on no register that covered what the transactions on record couldn't. Pain was easy to kill. That was the first and most dangerous truth the corridor taught him.", "noIndent": false}, {"id": "ch03-n04", "kind": "narrator", "text": "Gateway Drive. The first apartment with his name on it alone. A mirror coffee table, circle-cut, mounted on a spin — the kind of furniture that tells you exactly what era it belongs to without a word of explanation, and a razor that lived permanently in its corner like a fixture nobody remembered installing. The room had its own economy. The Wire Shop counter was the day job. The circle table was the night shift.", "html": "Gateway Drive. The first apartment with his name on it alone. A mirror coffee table, circle-cut, mounted on a spin — the kind of furniture that tells you exactly what era it belongs to without a word of explanation, and a razor that lived permanently in its corner like a fixture nobody remembered installing. The room had its own economy. The Wire Shop counter was the day job. The circle table was the night shift.", "noIndent": false}, {"id": "ch03-n05", "kind": "narrator", "text": "A house full of people with nobody in the room. Just his thoughts, getting louder.", "html": "A house full of people with nobody in the room. Just his thoughts, getting louder.", "noIndent": false}, {"id": "ch03-b07", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch03-n06", "kind": "narrator", "text": "The First Son was born.", "html": "The First Son was born.", "noIndent": true}, {"id": "ch03-n07", "kind": "narrator", "text": "He was so proud he didn't know what to do with his hands. Scared and proud at the same time — not competing feelings, the same feeling with two names. The boy was so small. He held him and did not know what to do. He was not good at being a father yet. He knew it in real time. He held him anyway.", "html": "He was so proud he didn't know what to do with his hands. Scared and proud at the same time — not competing feelings, the same feeling with two names. The boy was so small. He held him and did not know what to do. He was not good at being a father yet. He knew it in real time. He held him anyway.", "noIndent": false}, {"id": "ch03-n08", "kind": "narrator", "text": "Amazing. That is the only word that survives the translation. He would not trade it. Not a second. He only wished the tools had already been in place when the boy arrived — that the scar had already been processed, the hallways already walked, the lesson already learned. He got the child before he got the equipment. That's not a complaint. That's just the order it came in.", "html": "Amazing. That is the only word that survives the translation. He would not trade it. Not a second. He only wished the tools had already been in place when the boy arrived — that the scar had already been processed, the hallways already walked, the lesson already learned. He got the child before he got the equipment. That's not a complaint. That's just the order it came in.", "noIndent": false}, {"id": "ch03-n09", "kind": "narrator", "text": "The Early Cold had a verdict ready before the closing argument. Said it standing in a doorway with her arms already crossed, like she'd rehearsed the stance more than the words.", "html": "The Early Cold had a verdict ready before the closing argument. Said it standing in a doorway with her arms already crossed, like she'd rehearsed the stance more than the words.", "noIndent": false}, {"id": "ch03-n10", "kind": "narrator", "text": "\"You'll be nothing. Just like your father.\"", "html": "\"You'll be nothing. Just like your father.\"", "noIndent": true}, {"id": "ch03-n11", "kind": "narrator", "text": "She delivered it clean. No heat. Just the sentence, set down flat on the table and left there for him to pick up or step over. Thirteen months after the birth, the deadbolt closed. He picked up the pace because stopping meant sitting with the verdict, and the verdict was loud in a quiet room.", "html": "She delivered it clean. No heat. Just the sentence, set down flat on the table and left there for him to pick up or step over. Thirteen months after the birth, the deadbolt closed. He picked up the pace because stopping meant sitting with the verdict, and the verdict was loud in a quiet room.", "noIndent": false}, {"id": "ch03-b14", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch03-n12", "kind": "narrator", "text": "While he was trying to build a wall, the bedrock gave out underneath him.", "html": "While he was trying to build a wall, the bedrock gave out underneath him.", "noIndent": true}, {"id": "ch03-n13", "kind": "narrator", "text": "His own father lost the house. Losing a man to death has a shape to it — you can point to the moment, hold the date in your hand like a stone. Losing a man to The Glass Ghost is something else entirely. You can see the body standing right in front of you and understand that nobody is home. The door is open and the room is empty.", "html": "His own father lost the house. Losing a man to death has a shape to it — you can point to the moment, hold the date in your hand like a stone. Losing a man to The Glass Ghost is something else entirely. You can see the body standing right in front of you and understand that nobody is home. The door is open and the room is empty.", "noIndent": false}, {"id": "ch03-s02", "kind": "spoken", "text": "I saw what The Glass Ghost did to the one person I looked up to. And it ended him.", "html": "I saw what The Glass Ghost did to the one person I looked up to. And it ended him.", "audio": "/audio/spoken/ch03-s02.mp3"}, {"id": "ch03-n14", "kind": "narrator", "text": "A doorframe. A man he recognized standing in it. The light wrong. The posture wrong. The room behind him empty in a way rooms shouldn't be. He understood something in that doorframe — understood it the way a man understands something he does not yet have the language for. He understood it not as an abstraction but as a specific person he had loved. He saw the destination. He saw the end state. He filed it away in whatever part of him was still keeping notes.", "html": "A doorframe. A man he recognized standing in it. The light wrong. The posture wrong. The room behind him empty in a way rooms shouldn't be. He understood something in that doorframe — understood it the way a man understands something he does not yet have the language for. He understood it not as an abstraction but as a specific person he had loved. He saw the destination. He saw the end state. He filed it away in whatever part of him was still keeping notes.", "noIndent": false}, {"id": "ch03-n15", "kind": "narrator", "text": "Then he went back to Gateway Drive and sat at the spinning table in the dark.", "html": "Then he went back to Gateway Drive and sat at the spinning table in the dark.", "noIndent": false}, {"id": "ch03-n16", "kind": "narrator", "text": "Nothing. Just like your father.", "html": "<em>Nothing. Just like your father.</em>", "noIndent": true}, {"id": "ch03-n17", "kind": "narrator", "text": "He sat with that a long time.", "html": "He sat with that a long time.", "noIndent": true}, {"id": "ch03-b22", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch03-n18", "kind": "narrator", "text": "The estate sale happened on a Tuesday.", "html": "The estate sale happened on a Tuesday.", "noIndent": true}, {"id": "ch03-n19", "kind": "narrator", "text": "One day. No truck. No help. No one coming. Strangers walking the hallways, opening drawers, holding up the artifacts of a family and naming a price. Trophies. Plaques. Medals. A lifetime in sport — every game played, every line run, every morning woken up before light — laid out on tables. Strangers turned them over in their hands. Checked for scratches. Put them back down or tucked them under an arm. The names on the back meant nothing to anyone in that room except the boy watching it happen.", "html": "One day. No truck. No help. No one coming. Strangers walking the hallways, opening drawers, holding up the artifacts of a family and naming a price. Trophies. Plaques. Medals. A lifetime in sport — every game played, every line run, every morning woken up before light — laid out on tables. Strangers turned them over in their hands. Checked for scratches. Put them back down or tucked them under an arm. The names on the back meant nothing to anyone in that room except the boy watching it happen.", "noIndent": false}, {"id": "ch03-n20", "kind": "narrator", "text": "His mother had built a pond in the backyard with her own hands. His father had built a Tiki Bar on the side of the house. Evidence of people who had made something. The glass gone out of the man who built it.", "html": "His mother had built a pond in the backyard with her own hands. His father had built a Tiki Bar on the side of the house. Evidence of people who had made something. The glass gone out of the man who built it.", "noIndent": false}, {"id": "ch03-n21", "kind": "narrator", "text": "The neighbors didn't come out. Not one. People who had watched him learn to walk, who had eaten at that table, who had borrowed tools from that garage — they went inside and pulled their blinds. The street was quiet the way streets go quiet when everyone decides not to see something.", "html": "The neighbors didn't come out. Not one. People who had watched him learn to walk, who had eaten at that table, who had borrowed tools from that garage — they went inside and pulled their blinds. The street was quiet the way streets go quiet when everyone decides not to see something.", "noIndent": false}, {"id": "ch03-s03", "kind": "spoken", "text": "That silence was louder than the strangers. Louder than the cash. Louder than anything that happened inside that house that day. It is still the loudest thing I have ever heard.", "html": "That silence was louder than the strangers. Louder than the cash. Louder than anything that happened inside that house that day. It is still the loudest thing I have ever heard.", "audio": "/audio/spoken/ch03-s03.mp3"}, {"id": "ch03-n22", "kind": "narrator", "text": "They locked the door behind him like he was the one who didn't belong there.", "html": "They locked the door behind him like he was the one who didn't belong there.", "noIndent": false}, {"id": "ch03-n23", "kind": "narrator", "text": "He kept moving. Motion is medication. The body applied the rule even when the mind wasn't sure there was anything left worth applying it to.", "html": "He kept moving. Motion is medication. The body applied the rule even when the mind wasn't sure there was anything left worth applying it to.", "noIndent": true}]}, {"id": "ch-04", "number": "Chapter Four", "title": "Two Engines & The Limestone Field", "date": "", "studio": "/audio/chapters/ch-04.mp3", "blocks": [{"id": "ch04-n01", "kind": "narrator", "text": "He worked two shifts because the arithmetic offered no other exit.", "html": "He worked two shifts because the arithmetic offered no other exit.", "noIndent": true}, {"id": "ch04-n02", "kind": "narrator", "text": "The Red Label Line. Midnight shifts. HAZMAT certified. Sorting, stacking, and throwing heavy freight in the freezing terminal bays before the sun had cleared the tree line. Then the daytime shift at The High-Rise Carrier. The retail uniform, the headset, the sales targets. He ran both operations side-by-side, for four solid years, because the legal ledger didn't care where the money came from — only that it cleared.", "html": "The Red Label Line. Midnight shifts. HAZMAT certified. Sorting, stacking, and throwing heavy freight in the freezing terminal bays before the sun had cleared the tree line. Then the daytime shift at The High-Rise Carrier. The retail uniform, the headset, the sales targets. He ran both operations side-by-side, for four solid years, because the legal ledger didn't care where the money came from — only that it cleared.", "noIndent": false}, {"id": "ch04-n03", "kind": "narrator", "text": "He was trying to cut a path out. The Limestone Field. College football pads, lecture halls, a four-year degree. The clean blueprint of a man who could stand in front of his firstborn years down the road and say it out loud:", "html": "He was trying to cut a path out. The Limestone Field. College football pads, lecture halls, a four-year degree. The clean blueprint of a man who could stand in front of his firstborn years down the road and say it out loud:", "noIndent": false}, {"id": "ch04-s01", "kind": "spoken", "text": "I built a wall. I didn't just hide behind one.", "html": "I built a wall. I didn't just hide behind one.", "audio": "/audio/spoken/ch04-s01.mp3"}, {"id": "ch04-n04", "kind": "narrator", "text": "He made real friends there. He ran stairs for being late to practice — always late, always running, always arriving at something already in motion. The Limestone Field had a version of him that could have gone somewhere. But the Devil moved there with him.", "html": "He made real friends there. He ran stairs for being late to practice — always late, always running, always arriving at something already in motion. The Limestone Field had a version of him that could have gone somewhere. But the Devil moved there with him.", "noIndent": false}, {"id": "ch04-n05", "kind": "narrator", "text": "Whatever was already in the arsenal, the Limestone Field added a new elevation. The kind that made you the happiest person in any room. The kind that made the getting-down afterward feel like a tax worth paying, until it wasn't, and by the time it wasn't the habit was already a resident. Already paying rent. Already comfortable. Already looking at you like you owe it something.", "html": "Whatever was already in the arsenal, the Limestone Field added a new elevation. The kind that made you the happiest person in any room. The kind that made the getting-down afterward feel like a tax worth paying, until it wasn't, and by the time it wasn't the habit was already a resident. Already paying rent. Already comfortable. Already looking at you like you owe it something.", "noIndent": false}, {"id": "ch04-n06", "kind": "narrator", "text": "The blueprint required tuition. Tuition required cash. Cash required running two engines until the bearings glowed. The courtroom did not care about the blueprint. It noticed the income from the year of double shifts. It did not notice what those shifts had cost.", "html": "The blueprint required tuition. Tuition required cash. Cash required running two engines until the bearings glowed. The courtroom did not care about the blueprint. It noticed the income from the year of double shifts. It did not notice what those shifts had cost.", "noIndent": false}, {"id": "ch04-n07", "kind": "narrator", "text": "\"Your Honor, the income reflects a temporary period of overtime, not—\"", "html": "\"Your Honor, the income reflects a temporary period of overtime, not—\"", "noIndent": true}, {"id": "ch04-n08", "kind": "narrator", "text": "\"The number is the number.\"", "html": "\"The number is the number.\"", "noIndent": true}, {"id": "ch04-n09", "kind": "narrator", "text": "One isolated number, written in the ledger in the language the court used — cold, abstract, permanent. A figure that now owned a portion of everything he would ever earn.", "html": "One isolated number, written in the ledger in the language the court used — cold, abstract, permanent. A figure that now owned a portion of everything he would ever earn.", "noIndent": false}, {"id": "ch04-n10", "kind": "narrator", "text": "He closed the textbooks. Packed the gear. Went straight back to the loading dock.", "html": "He closed the textbooks. Packed the gear. Went straight back to the loading dock.", "noIndent": false}, {"id": "ch04-n11", "kind": "narrator", "text": "The degree stayed in the dirt. The Limestone Field became a ghost corridor. Another hallway that had looked like an exit and turned out to be another way deeper in.", "html": "The degree stayed in the dirt. The Limestone Field became a ghost corridor. Another hallway that had looked like an exit and turned out to be another way deeper in.", "noIndent": false}, {"id": "ch04-b13", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch04-n12", "kind": "narrator", "text": "The Loose Screw sat in the passenger seat and worked the frame the way rust works — slow, daily, committed. Every bar booth. Every morning drive. Every quiet second between songs.", "html": "The Loose Screw sat in the passenger seat and worked the frame the way rust works — slow, daily, committed. Every bar booth. Every morning drive. Every quiet second between songs.", "noIndent": true}, {"id": "ch04-n13", "kind": "narrator", "text": "\"You know nobody else would put up with you.\"", "html": "\"You know nobody else would put up with you.\"", "noIndent": true}, {"id": "ch04-n14", "kind": "narrator", "text": "He didn't answer. There wasn't an answer that shortened the ride. She hit him. More than once. More than twice. The math stopped mattering around the time the math started feeling normal.", "html": "He didn't answer. There wasn't an answer that shortened the ride. She hit him. More than once. More than twice. The math stopped mattering around the time the math started feeling normal.", "noIndent": false}, {"id": "ch04-n15", "kind": "narrator", "text": "The last time was the last time. That is the whole sentence.", "html": "The last time was the last time. That is the whole sentence.", "noIndent": false}, {"id": "ch04-n16", "kind": "narrator", "text": "He got the apartment. His sister moved in — real blood, solid ground, the kind that doesn't require maintenance or explanation. Every other weekend The First Son came. Forty-eight hours where the man in the apartment had to be a different version of himself. Steadier. Quieter. The kind of man a boy could rest against. He wasn't good at it. He showed up anyway.", "html": "He got the apartment. His sister moved in — real blood, solid ground, the kind that doesn't require maintenance or explanation. Every other weekend The First Son came. Forty-eight hours where the man in the apartment had to be a different version of himself. Steadier. Quieter. The kind of man a boy could rest against. He wasn't good at it. He showed up anyway.", "noIndent": false}, {"id": "ch04-n17", "kind": "narrator", "text": "That's what the record shows. He showed up.", "html": "That's what the record shows. He showed up.", "noIndent": false}, {"id": "ch04-b20", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch04-n18", "kind": "narrator", "text": "This happened before graduation. He was still a kid when The Kiss of Death walked up the breezeway. He heard the steps. He did not hide. He walked out and got in the man's face.", "html": "This happened before graduation. He was still a kid when The Kiss of Death walked up the breezeway. He heard the steps. He did not hide. He walked out and got in the man's face.", "noIndent": true}, {"id": "ch04-n19", "kind": "narrator", "text": "So you're here to shoot me.", "html": "<em>So you're here to shoot me.</em>", "noIndent": true}, {"id": "ch04-n20", "kind": "narrator", "text": "The man showed him the gun. Didn't say a word. Just showed it.", "html": "The man showed him the gun. Didn't say a word. Just showed it.", "noIndent": false}, {"id": "ch04-n21", "kind": "narrator", "text": "Then do it.", "html": "<em>Then do it.</em>", "noIndent": true}, {"id": "ch04-n22", "kind": "narrator", "text": "He didn't. The gun went back. The man left. The boy walked inside. She had been at the end of the street. Waiting on it to be done.", "html": "He didn't. The gun went back. The man left. The boy walked inside. She had been at the end of the street. Waiting on it to be done.", "noIndent": false}, {"id": "ch04-b26", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch04-n23", "kind": "narrator", "text": "Seven years later — seven years — he and The Architect got back together. They had a son. The Boy in the Wind. For a moment it looked like something that could work. He could love both his sons in the same room at the same time. He didn't clock the exits.", "html": "Seven years later — <em>seven years</em> — he and The Architect got back together. They had a son. The Boy in the Wind. For a moment it looked like something that could work. He could love both his sons in the same room at the same time. He didn't clock the exits.", "noIndent": true}, {"id": "ch04-n24", "kind": "narrator", "text": "The weekends started going wrong. Every weekend he had The First Son, she left. Not a coincidence — a policy. She started telling him to choose. He could not choose. He would never choose. A man who throws himself into six lanes of traffic to save a friend does not choose between his children.", "html": "The weekends started going wrong. Every weekend he had The First Son, she left. Not a coincidence — a policy. She started telling him to choose. He could not choose. He would never choose. A man who throws himself into six lanes of traffic to save a friend does not choose between his children.", "noIndent": false}]}, {"id": "ch-05", "number": "Chapter Five", "title": "The War Before the First Breath", "date": "", "studio": "/audio/chapters/ch-05.mp3", "blocks": [{"id": "ch05-n01", "kind": "narrator", "text": "The war started before the child had a pulse on an ultrasound.", "html": "The war started before the child had a pulse on an ultrasound.", "noIndent": true}, {"id": "ch05-n02", "kind": "narrator", "text": "He fought her off the clinic steps. He fought her off the adoption agencies. He stood in the living room and laid his title down with both hands: I will take full custody. Sign him over to me. She looked him in the face and said: Never.", "html": "He fought her off the clinic steps. He fought her off the adoption agencies. He stood in the living room and laid his title down with both hands: <em>I will take full custody. Sign him over to me.</em> She looked him in the face and said: <em>Never.</em>", "noIndent": false}, {"id": "ch05-n03", "kind": "narrator", "text": "The Boy in the Wind was born anyway. Dropped straight into a crossfire zeroed in before his lungs took their first breath.", "html": "The Boy in the Wind was born anyway. Dropped straight into a crossfire zeroed in before his lungs took their first breath.", "noIndent": false}, {"id": "ch05-n04", "kind": "narrator", "text": "He held him. Family had been told to go home. Not allowed in — not today, not on her terms. Just the two of them in that room. The boy looked up. He looked back. Just the two of them, in the space she couldn't take.", "html": "He held him. Family had been told to go home. Not allowed in — not today, not on her terms. Just the two of them in that room. The boy looked up. He looked back. Just the two of them, in the space she couldn't take.", "noIndent": false}, {"id": "ch05-n05", "kind": "narrator", "text": "Amazing.", "html": "<em>Amazing.</em>", "noIndent": true}, {"id": "ch05-n06", "kind": "narrator", "text": "Both sons had given him that word, each time meaning something different, each time meaning exactly the same thing.", "html": "Both sons had given him that word, each time meaning something different, each time meaning exactly the same thing.", "noIndent": false}, {"id": "ch05-b07", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch05-n07", "kind": "narrator", "text": "He was a natural on the asphalt. The Iron Yard. North Alabama automotive lot, gravel and diesel. He could read the posture of a customer before they hit the showroom door — locate the exact space between what a buyer said they could afford and what they were terrified of losing. Commission was the only vehicle that paid fast enough to keep the legal threats at bay. He worked it because he was good at it, and being good at something was something to hold.", "html": "He was a natural on the asphalt. The Iron Yard. North Alabama automotive lot, gravel and diesel. He could read the posture of a customer before they hit the showroom door — locate the exact space between what a buyer said they could afford and what they were terrified of losing. Commission was the only vehicle that paid fast enough to keep the legal threats at bay. He worked it because he was good at it, and being good at something was something to hold.", "noIndent": true}, {"id": "ch05-n08", "kind": "narrator", "text": "Then the floor buckled. Painkillers first. Then selling to support the habit. The mark landed in the state database. A permanent record does not negotiate. It waits quietly for twenty years, showing up at background checks and HR desks with the patience of a man who has nowhere else to be.", "html": "Then the floor buckled. Painkillers first. Then selling to support the habit. The mark landed in the state database. A permanent record does not negotiate. It waits quietly for twenty years, showing up at background checks and HR desks with the patience of a man who has nowhere else to be.", "noIndent": false}, {"id": "ch05-s01", "kind": "spoken", "text": "The pain was hard to wash away without a killer. You put the two together.", "html": "The pain was hard to wash away without a killer. You put the two together.", "audio": "/audio/spoken/ch05-s01.mp3"}, {"id": "ch05-n09", "kind": "narrator", "text": "The killer didn't arrive with sirens. It came as a quiet liquid pour at the end of a fourteen-hour turn. Something to take the jagged edges off the court docket, soften the memory of the gun at the door, put a buffer between his ribs and the woman holding his second son behind a state line he couldn't cross.", "html": "The killer didn't arrive with sirens. It came as a quiet liquid pour at the end of a fourteen-hour turn. Something to take the jagged edges off the court docket, soften the memory of the gun at the door, put a buffer between his ribs and the woman holding his second son behind a state line he couldn't cross.", "noIndent": false}, {"id": "ch05-n10", "kind": "narrator", "text": "The killer was patient. It had all the time in the world, and it knew something the man did not: that a thing you pick up to manage the pain has no interest in the pain ending. It makes itself necessary. It is very good at this.", "html": "The killer was patient. It had all the time in the world, and it knew something the man did not: that a thing you pick up to manage the pain has no interest in the pain ending. It makes itself necessary. It is very good at this.", "noIndent": false}, {"id": "ch05-b13", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch05-n11", "kind": "narrator", "text": "He packed the car and drove north into exile because The Boy in the Wind was across the state line. That was the whole reason. The only compass he had left.", "html": "He packed the car and drove north into exile because The Boy in the Wind was across the state line. That was the whole reason. The only compass he had left.", "noIndent": true}, {"id": "ch05-n12", "kind": "narrator", "text": "She owned the lease. He stayed within the four walls, raising the boy while she worked the day shift. She told him he was worthless. Daily. Like clockwork. He stopped arguing the point somewhere in the first month, because arguing it meant staying in the room a minute longer than he had to, and the room was where the word lived.", "html": "She owned the lease. He stayed within the four walls, raising the boy while she worked the day shift. She told him he was worthless. Daily. Like clockwork. He stopped arguing the point somewhere in the first month, because arguing it meant staying in the room a minute longer than he had to, and the room was where the word lived.", "noIndent": false}, {"id": "ch05-n13", "kind": "narrator", "text": "Until the day the arrangement ended in a sentence.", "html": "Until the day the arrangement ended in a sentence.", "noIndent": false}, {"id": "ch05-s02", "kind": "spoken", "text": "Be with my illiterate redneck faggot son.", "html": "Be with my illiterate redneck faggot son.", "audio": "/audio/spoken/ch05-s02.mp3"}, {"id": "ch05-n14", "kind": "narrator", "text": "He slapped her. Immediate regret, no hesitation, both things true in the same second. He ran out of the house and into a bar and drowned. Then the moving started. Then homeless came around. Then the only remaining direction was south.", "html": "He slapped her. Immediate regret, no hesitation, both things true in the same second. He ran out of the house and into a bar and drowned. Then the moving started. Then homeless came around. Then the only remaining direction was south.", "noIndent": false}, {"id": "ch05-s03", "kind": "spoken", "text": "Tuck tail and run.", "html": "Tuck tail and run.", "audio": "/audio/spoken/ch05-s03.mp3"}, {"id": "ch05-n15", "kind": "narrator", "text": "Except the tank was closer to empty than the wallet was to full, and the wallet wasn't close to anything. No cash for gas. No cash for anywhere else a man could disappear to. The only place left standing was back inside the same four walls, under the same word, waiting for the money to catch up to the plan.", "html": "Except the tank was closer to empty than the wallet was to full, and the wallet wasn't close to anything. No cash for gas. No cash for anywhere else a man could disappear to. The only place left standing was back inside the same four walls, under the same word, waiting for the money to catch up to the plan.", "noIndent": false}, {"id": "ch05-n16", "kind": "narrator", "text": "The dark taverns became the only sanctuary. A brutal, smoky holding cell when the walls started closing in. Bonfires out in the country. The back rooms. A rough, desperate version of himself running through the gravel lots — a man he will not defend and will not deny.", "html": "The dark taverns became the only sanctuary. A brutal, smoky holding cell when the walls started closing in. Bonfires out in the country. The back rooms. A rough, desperate version of himself running through the gravel lots — a man he will not defend and will not deny.", "noIndent": false}, {"id": "ch05-n17", "kind": "narrator", "text": "Then she orchestrated the evacuation. Surgical. He never saw the strike coming. Locks changed. Rooms emptied. The child removed while he was out of the house. He returned to a structure scrubbed of his existence.", "html": "Then she orchestrated the evacuation. Surgical. He never saw the strike coming. Locks changed. Rooms emptied. The child removed while he was out of the house. He returned to a structure scrubbed of his existence.", "noIndent": false}, {"id": "ch05-n18", "kind": "narrator", "text": "Homeless on the Eastside.", "html": "Homeless on the Eastside.", "noIndent": true}, {"id": "ch05-n19", "kind": "narrator", "text": "He stepped behind the bar. Pulling taps, slinging rail liquor at three hundred and fifty dollars a night.", "html": "He stepped behind the bar. Pulling taps, slinging rail liquor at three hundred and fifty dollars a night.", "noIndent": false}, {"id": "ch05-s04", "kind": "spoken", "text": "Strip bars serve ribeye at 7am if you stay up long enough.", "html": "Strip bars serve ribeye at 7am if you stay up long enough.", "audio": "/audio/spoken/ch05-s04.mp3"}, {"id": "ch05-n20", "kind": "narrator", "text": "Then she told him she was carrying his child again. He was so excited. He pleaded. He laid every argument down. He put every card on the table he had ever held and said every true thing available to him.", "html": "Then she told him she was carrying his child again. He was so excited. He pleaded. He laid every argument down. He put every card on the table he had ever held and said every true thing available to him.", "noIndent": false}, {"id": "ch05-n21", "kind": "narrator", "text": "The clinic doors closed anyway.", "html": "The clinic doors closed anyway.", "noIndent": false}, {"id": "ch05-s05", "kind": "spoken", "text": "The day I died more. With every breath I took imagining the breaths being stolen from my unborn child with nothing I could do to stop it.", "html": "The day I died more. With every breath I took imagining the breaths being stolen from my unborn child with nothing I could do to stop it.", "audio": "/audio/spoken/ch05-s05.mp3"}, {"id": "ch05-n22", "kind": "narrator", "text": "She packed the remainder of her life. She disappeared again. Moved.", "html": "She packed the remainder of her life. She disappeared again. Moved.", "noIndent": false}, {"id": "ch05-n23", "kind": "narrator", "text": "He walked out into the parking lot. Car dead. Pockets empty. The killer running through his bloodstream. Every road on the map ending in a wall. He stood in the dark and the dark just looked back at him.", "html": "He walked out into the parking lot. Car dead. Pockets empty. The killer running through his bloodstream. Every road on the map ending in a wall. He stood in the dark and the dark just looked back at him.", "noIndent": false}, {"id": "ch05-b31", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch05-n24", "kind": "narrator", "text": "He turned the radiator south and drove back toward Alabama. Not as a conqueror. Not with a single wound stitched closed, a single ledger balanced, a single thing in the car that amounted to a plan. He drove south because south was the only direction left.", "html": "He turned the radiator south and drove back toward Alabama. Not as a conqueror. Not with a single wound stitched closed, a single ledger balanced, a single thing in the car that amounted to a plan. He drove south because south was the only direction left.", "noIndent": true}, {"id": "ch05-s06", "kind": "spoken", "text": "The hallway didn't end when he crossed the state line. It just changed its wallpaper.", "html": "The hallway didn't end when he crossed the state line. It just changed its wallpaper.", "audio": "/audio/spoken/ch05-s06.mp3"}, {"id": "ch05-n25", "kind": "narrator", "text": "He kept walking.", "html": "He kept walking.", "noIndent": true}]}, {"id": "ch-06", "number": "Chapter Six", "title": "I See You, Brother", "date": "", "studio": "/audio/chapters/ch-06.mp3", "blocks": [{"id": "ch06-n01", "kind": "narrator", "text": "This is not a wound he gets to tell. It belongs to somebody else, and the book will not take it from him.", "html": "This is not a wound he gets to tell. It belongs to somebody else, and the book will not take it from him.", "noIndent": true}, {"id": "ch06-n02", "kind": "narrator", "text": "But there is one thing that needs saying straight at him, out loud, no third person standing between them this time.", "html": "But there is one thing that needs saying straight at him, out loud, no third person standing between them this time.", "noIndent": false}, {"id": "ch06-n03", "kind": "narrator", "text": "More than the scar. More than the ear. More than the knife left in his back, the cut around the waist all the way around, the cut around the thigh all the way around, the tricep. More than what they did to his body on that highway — it's the wound that was left behind. The wound he carries.", "html": "More than the scar. More than the ear. More than the knife left in his back, the cut around the waist all the way around, the cut around the thigh all the way around, the tricep. More than what they did to his body on that highway — it's the wound that was left behind. The wound he carries.", "noIndent": false}, {"id": "ch06-n04", "kind": "narrator", "text": "For the longest time he didn't know it was there. Tapioca was always somewhere else — the jungle, adventures, everywhere a man could imagine, happy and strong, like he had it all together. World traveler. Always. So he pushed himself to be like him. And every time he fell short, he went further into his own wounds, because he was nowhere near what the outside kept showing him.", "html": "For the longest time he didn't know it was there. Tapioca was always somewhere else — the jungle, adventures, everywhere a man could imagine, happy and strong, like he had it all together. World traveler. Always. So he pushed himself to be like him. And every time he fell short, he went further into his own wounds, because he was nowhere near what the outside kept showing him.", "noIndent": false}, {"id": "ch06-n05", "kind": "narrator", "text": "That's all that gets said about it here. The rest is his. His scars, his story, his version — and it's his to tell, not anyone else's. The space stays open.", "html": "That's all that gets said about it here. The rest is his. His scars, his story, his version — and it's his to tell, not anyone else's. The space stays open.", "noIndent": false}, {"id": "ch06-s01", "kind": "spoken", "text": "I see you, brother. I see you.", "html": "I see you, brother. I see you.", "audio": "/audio/spoken/ch06-s01.mp3"}, {"id": "ch06-n06", "kind": "narrator", "text": "And know that he sees him. Thinks about him even when he goes quiet. He isn't the easiest friend to have. Can go without calling, without the checkups. Can hide in his own shelter, his own world. It was never anything intentional.", "html": "And know that he sees him. Thinks about him even when he goes quiet. He isn't the easiest friend to have. Can go without calling, without the checkups. Can hide in his own shelter, his own world. It was never anything intentional.", "noIndent": false}, {"id": "ch06-n07", "kind": "narrator", "text": "I see. I see.", "html": "<em>I see. I see.</em>", "noIndent": true}, {"id": "ch06-b09", "kind": "break", "text": "— · —", "html": "— · —"}, {"id": "ch06-n08", "kind": "narrator", "text": "Here the page turns, and there is nothing on it. Front and back. Nothing.", "html": "Here the page turns, and there is nothing on it. Front and back. Nothing.", "noIndent": true}, {"id": "ch06-n09", "kind": "narrator", "text": "That is not an accident and it is not a mistake in the printing. It is the whole point. He has said everything that is his to say. The rest belongs to somebody else, if he ever chooses to write it. The door stays open. The light stays on.", "html": "That is not an accident and it is not a mistake in the printing. It is the whole point. He has said everything that is his to say. The rest belongs to somebody else, if he ever chooses to write it. The door stays open. The light stays on.", "noIndent": false}, {"id": "ch06-n10", "kind": "narrator", "text": "In a book that spends color like it's rationed, this is the one page that gets to be white and mean nothing but grace — held, offered, never demanded.", "html": "In a book that spends color like it's rationed, this is the one page that gets to be white and mean nothing but grace — held, offered, never demanded.", "noIndent": true}]}, {"id": "ch-07", "number": "Chapter Seven", "title": "The Cross", "date": "", "studio": "/audio/chapters/ch-07.mp3", "blocks": [{"id": "ch07-n01", "kind": "narrator", "text": "He carried the due date the way other men carry a wallet.", "html": "He carried the due date the way other men carry a wallet.", "noIndent": true}, {"id": "ch07-n02", "kind": "narrator", "text": "When it arrived he sat down. The shop smelled like green soap and burnt paper towel, the hum of the machine already up and idling before he'd even taken his shirt off.", "html": "When it arrived he sat down. The shop smelled like green soap and burnt paper towel, the hum of the machine already up and idling before he'd even taken his shirt off.", "noIndent": false}, {"id": "ch07-n03", "kind": "narrator", "text": "\"Big piece. You sure you want it there, over the scar like that?\"", "html": "\"Big piece. You sure you want it there, over the scar like that?\"", "noIndent": true}, {"id": "ch07-n04", "kind": "narrator", "text": "\"That's the point.\"", "html": "\"That's the point.\"", "noIndent": true}, {"id": "ch07-n05", "kind": "narrator", "text": "The artist didn't ask a second time. Some men in that chair are running from something. This one was clearly walking straight into it, and you don't slow a man like that down with more questions than he came in with.", "html": "The artist didn't ask a second time. Some men in that chair are running from something. This one was clearly walking straight into it, and you don't slow a man like that down with more questions than he came in with.", "noIndent": false}, {"id": "ch07-n06", "kind": "narrator", "text": "The Celtic Cross went on his back. A grave marker. For a child who never breathed. Pressed directly over the scar that had opened the whole book — the line drawn down the spine in the middle of six screaming lanes on Prom Night — sealed under ink and faith and grief so total it required permanent skin to hold it.", "html": "The Celtic Cross went on his back. A grave marker. For a child who never breathed. Pressed directly over the scar that had opened the whole book — the line drawn down the spine in the middle of six screaming lanes on Prom Night — sealed under ink and faith and grief so total it required permanent skin to hold it.", "noIndent": false}, {"id": "ch07-n07", "kind": "narrator", "text": "Two wounds. One mark. Stacked.", "html": "Two wounds. One mark. Stacked.", "noIndent": false}, {"id": "ch07-s01", "kind": "spoken", "text": "The cross covers the wound. The wound is still there. The cross knows.", "html": "The cross covers the wound. The wound is still there. The cross knows.", "audio": "/audio/spoken/ch07-s01.mp3"}, {"id": "ch07-n08", "kind": "narrator", "text": "The needle went in. The cross took shape over the spine. Below it — invisible now, but there always — the Prom Night line. The child's due date above it. The blade's first mark below. Buried under the only thing he had left to put over it.", "html": "The needle went in. The cross took shape over the spine. Below it — invisible now, but there always — the Prom Night line. The child's due date above it. The blade's first mark below. Buried under the only thing he had left to put over it.", "noIndent": false}, {"id": "ch07-n09", "kind": "narrator", "text": "Not redemption. Not yet. Not in this book.", "html": "Not redemption. Not yet. Not in this book.", "noIndent": false}, {"id": "ch07-n10", "kind": "narrator", "text": "This is only the headstone. Worn on a living man's back.", "html": "This is only the headstone. Worn on a living man's back.", "noIndent": true}]}, {"id": "ch-08", "number": "Close", "title": "The Last Witness", "date": "", "studio": "/audio/chapters/ch-08.mp3", "blocks": [{"id": "ch08-n01", "kind": "narrator", "text": "At the very end of the corridor, The Old Soldier is standing in the dark.", "html": "At the very end of the corridor, The Old Soldier is standing in the dark.", "noIndent": true}, {"id": "ch08-n02", "kind": "narrator", "text": "He was there when the blade hit the asphalt on Prom Night. He saw the blood. He saw the gun at the apartment door. He saw the dead car in a city where nobody knew the man's name. He saw the cross go on the back and he knows what it marks. Both things. He carries that without comment.", "html": "He was there when the blade hit the asphalt on Prom Night. He saw the blood. He saw the gun at the apartment door. He saw the dead car in a city where nobody knew the man's name. He saw the cross go on the back and he knows what it marks. Both things. He carries that without comment.", "noIndent": false}, {"id": "ch08-n03", "kind": "narrator", "text": "He does not speak. He does not step in. A witness bears the record. Holds the fact of a thing against the world's tendency to forget, to rewrite, to soften until it doesn't hurt anymore. He keeps the account honest.", "html": "He does not speak. He does not step in. A witness bears the record. Holds the fact of a thing against the world's tendency to forget, to rewrite, to soften until it doesn't hurt anymore. He keeps the account honest.", "noIndent": false}, {"id": "ch08-n04", "kind": "narrator", "text": "No white ink. Not here. Not in this book. Grace has not been named. The criminal record is active. The boys are on the wrong side of walls he didn't build. The killer is in his blood. The cross on his back is grief, not shield.", "html": "No white ink. Not here. Not in this book. Grace has not been named. The criminal record is active. The boys are on the wrong side of walls he didn't build. The killer is in his blood. The cross on his back is grief, not shield.", "noIndent": false}, {"id": "ch08-n05", "kind": "narrator", "text": "Not yet.", "html": "Not yet.", "noIndent": true}, {"id": "ch08-s01", "kind": "spoken", "text": "The dark doesn't owe you a resolution. It just asks if you're still standing.", "html": "The dark doesn't owe you a resolution. It just asks if you're still standing.", "audio": "/audio/spoken/ch08-s01.mp3"}, {"id": "ch08-n06", "kind": "narrator", "text": "Barely. The cross a grave for two things. The killer in his veins. The scar below the ink that started the whole book — covered but never closed, present always, waiting under the only thing he had left to put over it.", "html": "Barely. The cross a grave for two things. The killer in his veins. The scar below the ink that started the whole book — covered but never closed, present always, waiting under the only thing he had left to put over it.", "noIndent": false}, {"id": "ch08-s02", "kind": "spoken", "text": "Still standing.", "html": "Still standing.", "audio": "/audio/spoken/ch08-s02.mp3"}, {"id": "ch08-n07", "kind": "narrator", "text": "The Old Soldier watches from the edge of the frame. Nods once. Not approval. Not comfort.", "html": "The Old Soldier watches from the edge of the frame. Nods once. Not approval. Not comfort.", "noIndent": false}, {"id": "ch08-n08", "kind": "narrator", "text": "Only: I saw it. I have it. The record is kept.", "html": "Only: <em>I saw it. I have it. The record is kept.</em>", "noIndent": false}]}];

export const allPlayable = chapters.flatMap((ch) =>
  ch.blocks.filter((b) => b.kind !== "break").map((b) => ({ chapterId: ch.id, block: b })),
);

